            self.image = nil        }                self.width = width        self.height = height                self.font = nil        self.color = nil            }        public init(image: Image?,                colorValues: RGBValues? = nil,                width: CGFloat? = nil,                height: CGFloat? = nil) {                if let image = image {            self.image = image        } else {            self.image = nil        }                self.width = width        self.height = height                self.font = nil                if let colorValues = colorValues {            self.color = RGBValues.getColor(value: colorValues)        } else {            self.color = nil        }    }#elseif os(macOS)    public init(_ image: CPlatformImage?, width: CGFloat? = nil, height: CGFloat? = nil) {                if let image = image {            self.image = Image(nsImage: image)        } else {            self.image = nil        }                self.width = width        self.height = height        self.color = nil        self.font = nil    }#endif}public extension Image {    static func systemImage(_ symbol: C_SystemImageName) -> Image {        return Image(systemName: symbol.rawValue)    }}